const equipment=(key,label,body)=>`<g class="equipment" data-equip="${key}" role="button" tabindex="0" aria-label="${label}"><title>${label}</title>${body}</g>`;
const sensor=(key,name,unit,x,y,w=132)=>`<g class="sensor" data-sensor="${key}" role="button" tabindex="0" aria-label="${name}" transform="translate(${x} ${y})"><rect width="${w}" height="63" rx="6"/><circle cx="12" cy="14" r="2.5" fill="#a8ce8e"/><text x="21" y="18" class="sensor-name">${name}</text><text x="11" y="45" class="sensor-value" data-read="${key}">—</text><text x="${w-10}" y="46" text-anchor="end" class="unit">${unit}</text></g>`;
const pipe=(d,color,kind)=>`<path d="${d}" class="pipe-outline"/><path d="${d}" class="pipe" stroke="${color}"/><path d="${d}" class="pipe-flow ${kind}" style="animation-duration:4s"/>`;
