export function updateDiagram(r,row){const svg=document.querySelector('.process-svg');if(!svg)return;svg.classList.toggle('paused',!r.running);for(const kind of ['feed','gas','alk','effluent']){const active=kind==='feed'?row.feed>0:kind==='gas'?row.trueGas>.0001:kind==='effluent'?(row.feed>0||r.state.pendingAlk>.00001):r.state.pendingAlk>.00001;svg.querySelectorAll('.'+kind+'-flow').forEach(e=>{e.classList.toggle('off',!active);e.style.animationDuration=(kind==='feed'?Math.max(.8,8/(row.feed||1)):kind==='gas'?Math.max(1,4/(row.trueGas||1)):3)+'s';});}const impeller=svg.querySelector('.impeller');impeller.style.animationDuration=(5-4*r.controls.mix/100)+'s';impeller.style.animationPlayState=r.running&&r.controls.mixer&&r.controls.mix>0?'running':'paused';svg.querySelectorAll('.bubble').forEach(e=>{e.style.animationDuration=Math.max(2,6/(row.trueGas||.1))+'s';e.style.display=row.trueGas>.0001?'':'none';});const liquid=svg.querySelector('#feed-liquid');const h=130*r.state.feedVolume/50;liquid.setAttribute('y',471-h);liquid.setAttribute('height',h);}
